import type { Question } from '../../lib/types'
export const serverless_containers_questions: Question[] = [
  { id: 'd3-svc-001', domain: 3, topics: ['Lambda', 'cold start', 'Provisioned Concurrency'], type: 'single', stem: 'A Java Lambda function has 3-second cold starts affecting user experience. What is the most direct way to eliminate cold starts?', options: [{ id: 'A', text: 'Increase Lambda memory' }, { id: 'B', text: 'Enable Lambda Provisioned Concurrency' }, { id: 'C', text: 'Reduce the Lambda deployment package size' }, { id: 'D', text: 'Switch to the Python runtime' }], correct: ['B'], explanation: 'Provisioned Concurrency initializes a specified number of Lambda execution environments in advance. Requests are handled immediately with no cold start delay. Best for latency-sensitive applications.', distractors: { A: 'More memory speeds up initialization but does not eliminate cold starts — Provisioned Concurrency is the definitive solution.', C: 'Smaller packages reduce cold start duration marginally — do not eliminate the cold start.', D: 'Python has faster cold starts than Java but Provisioned Concurrency eliminates them entirely regardless of runtime.' } },
  { id: 'd3-svc-002', domain: 3, topics: ['Lambda', 'reserved concurrency', 'throttling'], type: 'single', stem: 'A Lambda function processes user requests and traffic spikes cause throttling errors. What concurrency type can both guarantee capacity and limit maximum usage per function?', options: [{ id: 'A', text: 'Account concurrency limit' }, { id: 'B', text: 'Reserved concurrency' }, { id: 'C', text: 'Burst concurrency' }, { id: 'D', text: 'Provisioned concurrency' }], correct: ['B'], explanation: 'Reserved concurrency: (1) guarantees the function can always get that many concurrent executions, (2) limits the function from consuming more. Protects other functions from one function exhausting the account concurrency pool.', distractors: { A: 'Account limit is shared across all functions in the region — not a per-function reservation.', C: 'Burst concurrency is the initial scaling rate from zero — not a per-function reservation or cap.', D: 'Provisioned concurrency pre-warms environments for cold start elimination — different from reserved concurrency.' } },
  { id: 'd3-svc-003', domain: 3, topics: ['Lambda', 'memory', 'CPU scaling'], type: 'single', stem: 'A Lambda function processing large files is slow despite optimized code. It is allocated 256 MB. What should be adjusted to get more compute?', options: [{ id: 'A', text: 'Increase the Lambda function timeout' }, { id: 'B', text: 'Increase Lambda memory' }, { id: 'C', text: 'Enable enhanced networking on the Lambda function for faster I/O' }, { id: 'D', text: 'Use Lambda@Edge instead' }], correct: ['B'], explanation: 'Lambda CPU is not a separate configuration — it scales proportionally with memory. For CPU-bound workloads, increasing memory to 1,792 MB grants 1 full vCPU. Doubling memory approximately doubles compute but also increases cost per GB-second.', distractors: { A: 'Timeout increase prevents timeout errors — does not speed up execution for the same computation.', C: 'Lambda has no enhanced networking configuration — it is a managed execution environment.', D: 'Lambda@Edge has lower memory limits (128 MB-10 GB) and is for CloudFront integration — not general compute scaling.' } },
  { id: 'd3-svc-004', domain: 3, topics: ['ECS', 'Fargate', 'task sizing'], type: 'single', stem: 'An ECS Fargate task needs 2 vCPU and 8 GB memory. How is this configured?', options: [{ id: 'A', text: 'Set instance type to c5.large in the ECS cluster settings' }, { id: 'B', text: 'Set task-level CPU (2048 units = 2 vCPU) and memory (8192 MB) in the task definition' }, { id: 'C', text: 'Fargate uses fixed compute for all tasks' }, { id: 'D', text: 'Configure container minimum memory reservation only' }], correct: ['B'], explanation: 'Fargate uses task-level CPU and memory configuration. CPU is in units (1024 = 1 vCPU). Valid CPU/memory combinations are predefined by AWS. The task runs on shared infrastructure sized to these specs — no instance selection needed.', distractors: { A: 'Fargate is serverless — no instance type selection. AWS manages the underlying infrastructure.', C: 'Fargate absolutely requires CPU/memory configuration in the task definition — it is not fixed.', D: 'Task-level CPU and memory are required for Fargate — not optional or auto-derived.' } },
  { id: 'd3-svc-005', domain: 3, topics: ['Lambda', 'container images', 'large dependencies'], type: 'single', stem: 'A Lambda function requires Python libraries totaling 500 MB. ZIP packages are limited to 50 MB (direct upload) or 250 MB (S3). What enables deployment of this dependency set?', options: [{ id: 'A', text: 'Split into multiple smaller Lambda functions with separate dependency sets' }, { id: 'B', text: 'Deploy Lambda as a container image' }, { id: 'C', text: 'Use Lambda Layers' }, { id: 'D', text: 'Store libraries in S3 and download at runtime during the init phase' }], correct: ['B'], explanation: 'Lambda container images support up to 10 GB (uncompressed). Push the image to ECR and reference it in the function. Allows standard Docker tooling, custom runtimes, and large dependency sets beyond ZIP limits.', distractors: { A: 'Splitting into multiple functions complicates architecture — container images solve the size problem directly.', C: 'Lambda Layers are limited to 250 MB total across all layers — insufficient for 500 MB dependencies.', D: 'Downloading libraries at runtime increases cold start time and adds failure risk — container images are the correct solution.' } },
  { id: 'd3-svc-006', domain: 3, topics: ['EKS', 'Managed Node Groups', 'patching'], type: 'single', stem: 'An EKS cluster needs worker nodes that AWS patches and manages automatically during updates. What EKS node type provides this?', options: [{ id: 'A', text: 'Self-managed node groups' }, { id: 'B', text: 'EKS Managed Node Groups' }, { id: 'C', text: 'EKS Fargate profiles' }, { id: 'D', text: 'AWS Batch with EKS integration' }], correct: ['B'], explanation: 'EKS Managed Node Groups provision EC2 instances, manage ASGs, and handle node updates (including cordoning, draining, and replacing nodes). Reduces operational overhead vs. self-managed while retaining EC2 flexibility.', distractors: { A: 'Self-managed nodes require the customer to handle AMI updates, patching, and lifecycle management manually.', C: 'Fargate profiles eliminate node management entirely but have limitations: no DaemonSets, no GPU, some addons unsupported.', D: 'AWS Batch is a separate batch workload service — not a Kubernetes node management solution.' } },
  { id: 'd3-svc-007', domain: 3, topics: ['Lambda', 'SQS event source', 'scaling'], type: 'single', stem: 'A Lambda function processes SQS messages but cannot keep up with the queue depth during high load. What Lambda feature helps scale processing automatically?', options: [{ id: 'A', text: 'Set Lambda reserved concurrency to 5' }, { id: 'B', text: 'Event source mapping auto-scaling' }, { id: 'C', text: 'Enable SQS long polling' }, { id: 'D', text: 'Increase SQS message visibility timeout' }], correct: ['B'], explanation: 'Lambda SQS event source mapping scales automatically by adding poller processes as queue depth grows — up to 1,000 concurrent executions. Lambda manages the scaling automatically based on queue depth.', distractors: { A: 'Reserved concurrency limits (not scales) processing — wrong direction for recovering from a backlog.', C: 'Long polling reduces empty API calls — does not change Lambda scaling behavior.', D: 'Visibility timeout controls message redelivery timing — not Lambda processing throughput.' } },
  { id: 'd3-svc-008', domain: 3, topics: ['ECS', 'auto scaling', 'target tracking'], type: 'single', stem: 'An ECS service needs to scale tasks based on CPU utilization, maintaining 70% as the target. What auto scaling policy achieves this?', options: [{ id: 'A', text: 'Scheduled auto scaling' }, { id: 'B', text: 'Target tracking on ECSServiceAverageCPUUtilization at 70%' }, { id: 'C', text: 'Step scaling with manual thresholds defined at 60%, 70%, and 80% CPU utilization' }, { id: 'D', text: 'Capacity provider strategies' }], correct: ['B'], explanation: 'ECS Service Auto Scaling target tracking monitors ECSServiceAverageCPUUtilization and adjusts task count to maintain the 70% target. Scales out when CPU exceeds target, scales in when below. Self-adjusting — no manual threshold configuration needed.', distractors: { A: 'Scheduled scaling handles predictable traffic patterns — not reactive to real-time CPU utilization.', C: 'Step scaling works but requires manual threshold configuration — target tracking is simpler and self-calibrating.', D: 'Capacity providers control which infrastructure type tasks run on — not metric-based task count scaling.' } },
  { id: 'd3-svc-009', domain: 3, topics: ['Lambda', 'ephemeral storage', '/tmp'], type: 'single', stem: 'A Lambda function downloads and processes an 800 MB file during execution. Default /tmp storage is 512 MB. What is the solution?', options: [{ id: 'A', text: 'Process the file using Python streaming' }, { id: 'B', text: 'Configure Lambda ephemeral storage up to 10 GB' }, { id: 'C', text: 'Mount an EFS filesystem to Lambda for temporary large file processing' }, { id: 'D', text: 'Add the large file to a Lambda Layer' }], correct: ['B'], explanation: 'Lambda ephemeral storage (/tmp) is configurable from 512 MB to 10 GB. Configure the desired size in the function settings. Charged at $0.0000000309/GB-second above 512 MB. Ideal for temporary large file processing.', distractors: { A: 'Streaming requires the application to support chunk-based processing — increasing /tmp is simpler when file access is needed.', C: 'EFS provides persistent shared storage — useful but requires VPC configuration and has higher latency than local /tmp.', D: 'Lambda Layers are deployment packages mounted at /opt — not runtime scratch space for downloaded files.' } },
  { id: 'd3-svc-010', domain: 3, topics: ['ECS', 'awsvpc', 'task networking'], type: 'single', stem: 'Each ECS Fargate task needs its own security group and private IP address. What network mode is required?', options: [{ id: 'A', text: 'Bridge network mode' }, { id: 'B', text: 'awsvpc network mode' }, { id: 'C', text: 'Host network mode' }, { id: 'D', text: 'Overlay network mode' }], correct: ['B'], explanation: 'awsvpc mode provides each ECS task its own Elastic Network Interface, private IP, and security group — same networking model as EC2 instances. Required for Fargate. Enables task-level network isolation.', distractors: { A: 'Bridge mode shares the host\'s network namespace — tasks share security groups with the host, no individual task IPs.', C: 'Host mode uses the EC2 host network directly — no task isolation and not supported in Fargate.', D: 'Overlay/Docker Swarm networking is not an ECS network mode — ECS uses bridge, host, or awsvpc.' } },
  { id: 'd3-svc-011', domain: 3, topics: ['Lambda', 'Destinations', 'async routing'], type: 'single', stem: 'An async Lambda function should send successful results to SQS and failed results (after retries) to SNS. What Lambda feature routes outcomes to different destinations?', options: [{ id: 'A', text: 'Lambda DLQ' }, { id: 'B', text: 'Lambda Destinations' }, { id: 'C', text: 'try/except in Lambda code' }, { id: 'D', text: 'CloudWatch alarm on Lambda error metrics' }], correct: ['B'], explanation: 'Lambda Destinations route async invocation results: On Success and On Failure each go to separate destinations (SQS, SNS, EventBridge, or another Lambda). More flexible than DLQ which only handles failures.', distractors: { A: 'DLQ captures failed invocations only — cannot route successful results to a separate destination.', C: 'Code-level routing adds complexity and requires code changes — Destinations are configuration-only.', D: 'CloudWatch alarms trigger reactive actions on metrics — not real-time routing of individual Lambda invocation outcomes.' } },
  { id: 'd3-svc-012', domain: 3, topics: ['EKS', 'Fargate profiles', 'serverless Kubernetes'], type: 'single', stem: 'A team wants to run Kubernetes pods without managing EC2 worker nodes. What provides serverless Kubernetes pod execution?', options: [{ id: 'A', text: 'EKS Managed Node Groups' }, { id: 'B', text: 'EKS Fargate profiles' }, { id: 'C', text: 'ECS Fargate' }, { id: 'D', text: 'AWS Batch with EKS integration' }], correct: ['B'], explanation: 'EKS Fargate profiles define which pods (by namespace and label selectors) run on Fargate. AWS manages the underlying compute. No EC2 nodes to patch, scale, or manage. Limitations: no DaemonSets, no privileged containers.', distractors: { A: 'Managed Node Groups reduce node management but EC2 instances still exist — not serverless.', C: 'ECS Fargate uses ECS task definitions, not Kubernetes pods or kubectl — different orchestrator.', D: 'AWS Batch is a separate batch workload service — not Kubernetes serverless node execution.' } },
  { id: 'd3-svc-013', domain: 3, topics: ['Lambda', 'Layers', 'shared libraries'], type: 'single', stem: 'Three Lambda functions each package the same 40 MB library in their ZIP files. What reduces deployment package redundancy?', options: [{ id: 'A', text: 'Inline the library code directly into each function' }, { id: 'B', text: 'Create a Lambda Layer with the shared library' }, { id: 'C', text: 'Store the library in S3 and import it during the Lambda init phase' }, { id: 'D', text: 'Combine all three functions into one monolithic Lambda to share the library in-process' }], correct: ['B'], explanation: 'Lambda Layers package shared code/dependencies. Functions reference layers by ARN; the layer is mounted to /opt. Up to 5 layers per function (250 MB total unzipped). Reduces deployment package duplication and enables centralized library updates.', distractors: { A: 'Inlining duplicates code in each function — the opposite of reducing redundancy.', C: 'S3 download during init adds latency to every cold start — layers are pre-mounted with no runtime download.', D: 'Monolithic function combines unrelated logic — not appropriate for independent functions with a shared library.' } },
  { id: 'd3-svc-014', domain: 3, topics: ['Step Functions', 'workflow orchestration'], type: 'single', stem: 'An order processing workflow has 6 sequential steps (validate, inventory, payment, fulfill, notify, archive) with state passed between them and retry logic. What service orchestrates this?', options: [{ id: 'A', text: 'Lambda chaining' }, { id: 'B', text: 'AWS Step Functions' }, { id: 'C', text: 'SQS chaining' }, { id: 'D', text: 'EventBridge rules with Lambda targets' }], correct: ['B'], explanation: 'Step Functions provides a managed state machine. Define workflow steps, transitions, retries, timeouts, and error handling in JSON/YAML (Amazon States Language). State is automatically passed between steps. Visual workflow debugging.', distractors: { A: 'Lambda chaining creates tight coupling between functions and brittle error handling — Step Functions manages this externally.', C: 'SQS chaining requires a Lambda consumer per queue with no state visibility — operationally complex.', D: 'EventBridge rules trigger on events — not sequential workflow orchestration with state passing and retries.' } },
  { id: 'd3-svc-015', domain: 3, topics: ['Lambda', 'timeout', 'long-running tasks'], type: 'single', stem: 'A Lambda function triggers a process that takes 20 minutes. Lambda has a 15-minute maximum timeout. What architecture handles this?', options: [{ id: 'A', text: 'Increase Lambda timeout beyond 15 minutes' }, { id: 'B', text: 'Lambda triggers an ECS Fargate task or Step Functions workflow' }, { id: 'C', text: 'Split into multiple Lambda functions of 4 minutes each, chained sequentially' }, { id: 'D', text: 'Use Lambda@Edge' }], correct: ['B'], explanation: 'Lambda\'s hard maximum is 15 minutes and cannot be exceeded. For longer workloads: trigger an ECS task (no time limit), Step Functions workflow, AWS Batch job, or EC2 process. Lambda fires the trigger and returns immediately.', distractors: { A: 'Lambda maximum timeout is 15 minutes — it cannot be increased via Support or any configuration.', C: 'Splitting into sequential Lambda functions requires solving orchestration — Step Functions handles this more cleanly.', D: 'Lambda@Edge timeout is 5 seconds (viewer) or 30 seconds (origin) — far less than 15 minutes, not an option.' } },
  { id: 'd3-svc-016', domain: 3, topics: ['ECS', 'Fargate Spot', 'cost optimization'], type: 'single', stem: 'An ECS batch workload can tolerate interruptions with graceful shutdown. What Fargate configuration reduces cost significantly?', options: [{ id: 'A', text: 'Fargate Compute Savings Plans' }, { id: 'B', text: 'Fargate Spot' }, { id: 'C', text: 'Fargate reserved capacity' }, { id: 'D', text: 'ECS on On-Demand EC2' }], correct: ['B'], explanation: 'Fargate Spot uses spare Fargate capacity at up to 70% discount vs. on-demand. Tasks receive a 2-minute warning via ECS task state change event before interruption. Applications must handle graceful shutdown within 2 minutes.', distractors: { A: 'Compute Savings Plans require 1-year commitment — Fargate Spot provides larger discounts for interruptible workloads without commitment.', C: 'Fargate reserved capacity does not exist as a separate product — Savings Plans are the commitment option.', D: 'On-Demand EC2 with ECS loses the Fargate managed infrastructure benefit and does not provide the Spot-level discount.' } },
  { id: 'd3-svc-017', domain: 3, topics: ['Lambda', 'DynamoDB Streams', 'ordering'], type: 'single', stem: 'A Lambda function processes DynamoDB Streams events and must process events for each partition key in order. How does Lambda ensure ordering?', options: [{ id: 'A', text: 'Lambda processes all shard records in parallel across shards and partition keys simultaneously' }, { id: 'B', text: 'Lambda event source mapping processes each shard sequentially' }, { id: 'C', text: 'Configure DynamoDB Streams to sort records by timestamp before Lambda reads them' }, { id: 'D', text: 'Set Lambda reserved concurrency to 1' }], correct: ['B'], explanation: 'DynamoDB Streams records for a partition key always land in the same shard. Lambda processes each shard sequentially, preserving order within a shard. Different shards are processed in parallel. The parallelization factor (1-10) allows multiple batches per shard concurrently while maintaining per-batch order.', distractors: { A: 'Records within a shard are processed sequentially — only different shards are processed in parallel.', C: 'DynamoDB Streams does not offer user-configurable timestamp sorting — shard ordering is by write sequence.', D: 'Reserved concurrency=1 processes all records globally serial — a performance bottleneck that misunderstands shard-level ordering.' } },
  { id: 'd3-svc-018', domain: 3, topics: ['ECS', 'Cloud Map', 'service discovery'], type: 'single', stem: 'ECS microservices need to discover each other by service name via DNS without a load balancer. What provides service discovery for ECS?', options: [{ id: 'A', text: 'Hardcode IP addresses in environment variables' }, { id: 'B', text: 'AWS Cloud Map with ECS service discovery' }, { id: 'C', text: 'ALB with target groups per service' }, { id: 'D', text: 'API Gateway private integrations' }], correct: ['B'], explanation: 'ECS Service Discovery integrates with Cloud Map. When tasks start, they register DNS A records in a Route 53 private hosted zone. Other services resolve the service name to get task IPs directly — no load balancer needed for east-west traffic.', distractors: { A: 'Hardcoded IPs break when tasks are replaced — ECS task IPs change on every restart.', C: 'ALB adds cost and latency for east-west traffic — Cloud Map provides direct DNS-based discovery without a load balancer hop.', D: 'API Gateway is for external API exposure — not internal microservice-to-microservice DNS discovery.' } },
  { id: 'd3-svc-019', domain: 3, topics: ['Lambda', 'Function URL', 'HTTPS endpoint'], type: 'single', stem: 'A Lambda function needs to be invoked via HTTPS without API Gateway. What provides a dedicated HTTPS endpoint for Lambda?', options: [{ id: 'A', text: 'ALB with Lambda target group' }, { id: 'B', text: 'Lambda Function URLs' }, { id: 'C', text: 'Lambda@Edge' }, { id: 'D', text: 'CloudFront with Lambda as a custom origin' }], correct: ['B'], explanation: 'Lambda Function URLs provide a dedicated HTTPS endpoint (https://<url-id>.lambda-url.<region>.on.aws). Supports IAM authentication or no authentication. Useful for webhooks and simple APIs without API Gateway overhead.', distractors: { A: 'ALB with Lambda target works but adds cost and listener rule configuration — Function URL is simpler for direct HTTPS.', C: 'Lambda@Edge executes at CloudFront edges — not a standalone HTTPS endpoint for direct Lambda invocation.', D: 'CloudFront with Lambda origin adds CDN complexity and cost — Function URL is the direct solution.' } },
  { id: 'd3-svc-020', domain: 3, topics: ['EKS', 'Karpenter', 'node autoscaling'], type: 'single', stem: 'An EKS cluster needs to scale EC2 nodes quickly based on pending pods, provisioning right-sized instances for pod requirements. What AWS-native solution provides faster, cost-optimized node provisioning?', options: [{ id: 'A', text: 'Kubernetes Cluster Autoscaler' }, { id: 'B', text: 'Karpenter' }, { id: 'C', text: 'Manual EC2 Auto Scaling' }, { id: 'D', text: 'EKS Fargate only' }], correct: ['B'], explanation: 'Karpenter is an open-source AWS-native node provisioner. Watches for pending pods and provisions right-sized EC2 instances directly (no pre-defined node groups). Faster provisioning, better bin packing, Spot diversification, and consolidates underutilized nodes.', distractors: { A: 'Cluster Autoscaler scales at the node group level — slower and less flexible than Karpenter\'s direct instance provisioning.', C: 'Manual scaling ignores pod requirements — results in over/under-provisioning and requires human intervention.', D: 'Fargate has limitations (no DaemonSets, no GPU) and higher per-unit cost for consistent workloads.' } },
  { id: 'd3-svc-021', domain: 3, topics: ['Lambda', 'SnapStart', 'Java cold start'], type: 'single', stem: 'Java Lambda functions have 3+ second cold starts due to JVM initialization. What Lambda feature specifically addresses Java cold start performance?', options: [{ id: 'A', text: 'Provisioned Concurrency' }, { id: 'B', text: 'Lambda SnapStart for Java' }, { id: 'C', text: 'Increase Lambda memory to 10 GB' }, { id: 'D', text: 'Switch to GraalVM native image compilation' }], correct: ['B'], explanation: 'Lambda SnapStart (Java 11+) snapshots the initialized execution environment after the init phase. Cold starts resume from this snapshot (milliseconds) instead of re-running the full JVM startup. Up to 10x cold start improvement over standard Java.', distractors: { A: 'Provisioned Concurrency eliminates cold starts by pre-warming environments — SnapStart is a Java-specific optimization that also reduces cold start time at lower cost.', C: 'More memory speeds up initialization but does not eliminate JVM startup — SnapStart snapshots the initialized state.', D: 'GraalVM native image requires recompilation and has trade-offs — SnapStart works with standard JVM Java without code changes.' } },
  { id: 'd3-svc-022', domain: 3, topics: ['ECS', 'task placement', 'AZ spread'], type: 'single', stem: 'An ECS cluster runs tasks on EC2 instances across multiple AZs. To maximize availability, tasks should spread across AZs first, then across instances within each AZ. What placement strategy achieves this?', options: [{ id: 'A', text: 'Binpack strategy' }, { id: 'B', text: 'Spread on availability-zone attribute, then on instanceId' }, { id: 'C', text: 'Random placement strategy' }, { id: 'D', text: 'Fargate only' }], correct: ['B'], explanation: 'ECS task placement spread with attribute:ecs.availability-zone first distributes tasks across AZs. Adding a second spread by instanceId balances within each AZ. Maximizes fault tolerance against both instance and AZ failures.', distractors: { A: 'Binpack consolidates tasks on fewer instances to reduce cost — the opposite goal of spreading for availability.', C: 'Random placement does not guarantee AZ distribution — tasks could cluster in one AZ by chance.', D: 'Fargate does not support task placement strategies — placement strategies apply only to the EC2 launch type.' } },
  { id: 'd3-svc-023', domain: 3, topics: ['Lambda', 'EFS mount', 'shared files'], type: 'single', stem: 'Multiple Lambda invocations need to read and write shared files. Lambda /tmp is local to each execution environment. What provides shared persistent file access?', options: [{ id: 'A', text: 'Use S3 for all file operations' }, { id: 'B', text: 'Mount an EFS filesystem to Lambda' }, { id: 'C', text: 'Use DynamoDB for file storage' }, { id: 'D', text: 'Use ElastiCache Redis for file sharing' }], correct: ['B'], explanation: 'Lambda supports mounting EFS filesystems via access points. The Lambda function must be in a VPC with EFS connectivity. Multiple concurrent invocations share the same EFS filesystem — ideal for ML model files, shared datasets, and POSIX-style file access.', distractors: { A: 'S3 works for many use cases but requires S3 API calls — EFS provides POSIX file system semantics with standard file I/O APIs.', C: 'DynamoDB is a key-value/document store — not a filesystem for large binary files.', D: 'ElastiCache is an in-memory cache — not persistent file storage for large files that survive beyond cache TTL.' } },
  { id: 'd3-svc-024', domain: 3, topics: ['ECR', 'image pull', 'same-region'], type: 'single', stem: 'ECS task launch time is slow because container images pull from ECR across regions. How can image pull latency be reduced?', options: [{ id: 'A', text: 'Increase ECS task CPU allocation' }, { id: 'B', text: 'Use ECR in the same region as ECS and leverage image layer caching' }, { id: 'C', text: 'Use Docker Hub instead of ECR' }, { id: 'D', text: 'Store container images in S3 and have ECS download directly' }], correct: ['B'], explanation: 'Keep ECR and ECS in the same AWS region to avoid cross-region pull latency and data transfer costs. Image layer caching (Docker layer caching) means only changed layers are downloaded. For EC2 launch type, pre-pull images to warm the daemon cache.', distractors: { A: 'More CPU does not speed up network-bound image downloads — same-region ECR reduces the network latency.', C: 'Docker Hub is a public internet registry — higher latency and rate limits compared to regional ECR.', D: 'Container images are stored in OCI/Docker format — ECS cannot pull directly from S3; ECR is the supported registry.' } },
  { id: 'd3-svc-025', domain: 3, topics: ['Lambda', 'burst scaling', 'concurrency'], type: 'single', stem: 'A Lambda function goes from 0 to 10,000 concurrent requests suddenly. What is the initial scaling behavior?', options: [{ id: 'A', text: 'Lambda immediately scales to 10,000 concurrent executions' }, { id: 'B', text: 'Lambda scales to the initial burst limit (500-3,000 per region) then adds 500 concurrent executions per minute' }, { id: 'C', text: 'Lambda scales linearly at 100 new executions per minute up to the account limit' }, { id: 'D', text: 'Lambda is limited to 100 concurrent executions until the warm-up period completes after 5 minutes' }], correct: ['B'], explanation: 'Lambda burst scaling: initial burst capacity (500-3,000 per region) is reached immediately. After the initial burst, Lambda adds 500 concurrent executions per minute until reaching the account limit (1,000 default, adjustable). Requests exceeding capacity are throttled.', distractors: { A: 'Lambda has burst limits — immediately scaling to 10,000 is not guaranteed without prior scaling history.', C: '100 per minute is not the correct burst rate — Lambda scales much faster with the initial burst plus 500/minute.', D: '100 concurrent with a 5-minute warm-up is not how Lambda scaling works — burst capacity is available immediately.' } },
  { id: 'd3-svc-026', domain: 3, topics: ['App Runner', 'serverless containers', 'fully managed'], type: 'single', stem: 'A developer wants to deploy a containerized web app without managing VPCs, load balancers, or auto scaling. What fully managed service handles all infrastructure?', options: [{ id: 'A', text: 'ECS with Fargate and ALB' }, { id: 'B', text: 'AWS App Runner' }, { id: 'C', text: 'Elastic Beanstalk for containers' }, { id: 'D', text: 'Lambda with container images' }], correct: ['B'], explanation: 'App Runner is fully managed for containerized web apps. No VPC, load balancer, or auto scaling configuration required. Connect a GitHub repo or ECR image — App Runner builds, deploys, manages TLS, scales based on traffic, and can scale to zero.', distractors: { A: 'ECS Fargate + ALB requires VPC, subnets, listener rules, target groups, and task definitions — significant manual configuration.', C: 'Elastic Beanstalk still requires load balancer type, instance type, and VPC choices — more managed than EC2 but not fully hands-off.', D: 'Lambda has a 15-minute timeout and 10 GB memory limit — less suitable for traditional stateful web server applications.' } },
  { id: 'd3-svc-027', domain: 3, topics: ['Lambda', 'Power Tuning', 'cost optimization'], type: 'single', stem: 'A Lambda function costs $50/month. The team wants to find the optimal memory that minimizes total cost (duration × price per GB-second). What approach identifies the optimal configuration?', options: [{ id: 'A', text: 'Manually test each memory setting from 128 MB to 10 GB and compare CloudWatch duration metrics' }, { id: 'B', text: 'AWS Lambda Power Tuning' }, { id: 'C', text: 'Set memory to maximum (10 GB)' }, { id: 'D', text: 'Use CloudWatch Logs Insights to estimate duration at different memory levels from historical data' }], correct: ['B'], explanation: 'AWS Lambda Power Tuning is an open-source tool deployed as Step Functions. It runs the function at multiple memory configurations, measures duration and cost, and generates a visualization. Helps find the "sweet spot" between speed and cost.', distractors: { A: 'Manual testing is slow and error-prone — Power Tuning automates comparative testing across all memory settings simultaneously.', C: 'Maximum memory costs more per GB-second — optimal is often a middle value where the duration decrease outweighs the price increase.', D: 'CloudWatch Logs show actual durations at the current memory setting — not comparative data at other memory levels.' } },
  { id: 'd3-svc-028', domain: 3, topics: ['ECS', 'FireLens', 'log routing'], type: 'single', stem: 'ECS tasks need to send logs to CloudWatch, S3, and a third-party service without modifying application code. What AWS-native pattern enables multi-destination log routing?', options: [{ id: 'A', text: 'Add logging SDK calls to the application for each destination' }, { id: 'B', text: 'Sidecar container with manual Fluent Bit configuration' }, { id: 'C', text: 'CloudWatch agent on the EC2 host' }, { id: 'D', text: 'ECS FireLens' }], correct: ['D'], explanation: 'ECS FireLens integrates Fluent Bit or Fluentd as a sidecar for log routing. Configure destinations (CloudWatch, S3, Kinesis, Datadog, etc.) in the task definition. No application code changes — the app writes to stdout and FireLens routes the output.', distractors: { A: 'Application-level multi-destination logging couples the app to logging infrastructure and requires code changes.', B: 'ECS FireLens is the AWS-managed version of this pattern — it is the specific AWS feature that handles Fluent Bit sidecar lifecycle.', C: 'CloudWatch agent on the EC2 host requires instance access and does not manage container log routing to multiple destinations.' } },
  { id: 'd3-svc-029', domain: 3, topics: ['Lambda', 'Extensions', 'observability'], type: 'single', stem: 'A company uses Datadog to monitor Lambda functions. They need telemetry sent to Datadog without modifying Lambda function code. What mechanism enables this?', options: [{ id: 'A', text: 'Add Datadog SDK calls to each Lambda function' }, { id: 'B', text: 'Lambda Extensions' }, { id: 'C', text: 'CloudWatch Logs subscription filter to forward Lambda logs to Datadog automatically' }, { id: 'D', text: 'Lambda Layer with instrumentation code' }], correct: ['B'], explanation: 'Lambda Extensions allow external processes to run alongside the function in the same execution environment. Datadog and other observability vendors provide extensions that intercept telemetry, logs, and metrics without any function code changes.', distractors: { A: 'Adding SDK calls modifies every function — the opposite of code-change-free integration.', C: 'CloudWatch Logs subscription adds latency and only captures log output — Extensions operate at the Lambda execution level with richer telemetry.', D: 'Layers with instrumentation code still require importing the wrapper in each function\'s handler.' } },
  { id: 'd3-svc-030', domain: 3, topics: ['ECS', 'GPU', 'Fargate limitation'], type: 'single', stem: 'An ML inference workload runs in containers and requires GPU acceleration. Does Fargate support GPU?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes, with Fargate Spot only' }, { id: 'D', text: 'Yes' }], correct: ['B'], explanation: 'Fargate is serverless and does not expose GPU hardware. For GPU containerized workloads, use ECS with EC2 launch type on GPU instances (p3.2xlarge, g4dn.xlarge) or EKS with GPU worker nodes. SageMaker is also an option for ML inference.', distractors: { A: 'Fargate does not support GPU — this is a documented Fargate limitation.', C: 'Fargate Spot also does not support GPU — the limitation is architectural, not related to the pricing model.', D: 'EKS Fargate profiles also do not support GPU — the same Fargate infrastructure limitation applies.' } },
  { id: 'd3-svc-031', domain: 3, topics: ['Lambda', 'response streaming', 'progressive delivery'], type: 'single', stem: 'A Lambda function generates a large 5 MB HTML response. Users wait for the entire response before seeing anything. What Lambda capability sends data progressively?', options: [{ id: 'A', text: 'Increase Lambda payload limit to 10 MB' }, { id: 'B', text: 'Lambda response streaming' }, { id: 'C', text: 'Store the response in S3 and return a presigned URL for the client to download directly' }, { id: 'D', text: 'Increase Lambda timeout' }], correct: ['B'], explanation: 'Lambda response streaming allows functions to stream responses progressively. First bytes reach the client immediately without waiting for the full response. Supports up to 20 MB (vs. 6 MB synchronous limit). Requires Function URL or streaming-compatible API Gateway.', distractors: { A: 'Lambda synchronous payload is 6 MB — streaming addresses large responses differently and is not a limit increase.', C: 'S3 presigned URL adds a client round-trip — streaming is for real-time progressive delivery without redirection.', D: 'Timeout increase allows longer execution — does not enable the client to receive partial data before completion.' } },
  { id: 'd3-svc-032', domain: 3, topics: ['ECS', 'capacity providers', 'mixed fleet'], type: 'single', stem: 'An ECS cluster should run a baseline of 2 tasks on On-Demand EC2 and all additional tasks on Spot EC2 to minimize cost. What ECS feature enables this mixed strategy?', options: [{ id: 'A', text: 'Two separate ECS services' }, { id: 'B', text: 'ECS Capacity Providers with base=2 on On-Demand and weight on Spot' }, { id: 'C', text: 'Manual instance type selection in the task definition' }, { id: 'D', text: 'ECS Service Auto Scaling' }], correct: ['B'], explanation: 'ECS Capacity Providers with managed scaling: set base=2 on the On-Demand capacity provider (always runs 2 tasks there) and weight on the Spot provider for overflow. ECS managed scaling adjusts the underlying Auto Scaling Groups automatically.', distractors: { A: 'Two separate services split the workload — no unified scaling strategy that automatically routes overflow to Spot.', C: 'Task definitions do not specify On-Demand vs. Spot — this is determined by capacity providers and the launch template.', D: 'Service Auto Scaling scales task count — not the On-Demand/Spot split.' } },
  { id: 'd3-svc-033', domain: 3, topics: ['Lambda', 'arm64', 'Graviton2 cost'], type: 'single', stem: 'A Lambda function runs on x86. The team wants to reduce cost and improve performance. What Lambda architecture option improves price-performance?', options: [{ id: 'A', text: 'Increase memory to the maximum 10 GB' }, { id: 'B', text: 'Switch to arm64 (Graviton2)' }, { id: 'C', text: 'Use Lambda@Edge instead' }, { id: 'D', text: 'Enable Provisioned Concurrency' }], correct: ['B'], explanation: 'Lambda arm64 (Graviton2) costs 20% less per GB-second and typically runs faster for compute-bound workloads. For interpreted languages (Python, Node.js), switching requires only a Lambda configuration change — no code changes.', distractors: { A: 'More memory reduces duration at a higher per-GB-second cost — net savings depend on workload; arm64 provides 20% savings regardless.', C: 'Lambda@Edge pricing is different but not specifically cheaper — arm64 is the correct price-performance optimization.', D: 'Provisioned Concurrency eliminates cold starts but pre-allocates environments 24/7 — increases cost rather than reducing it.' } },
  { id: 'd3-svc-034', domain: 3, topics: ['ECS', 'ALB integration', 'auto registration'], type: 'single', stem: 'An ECS service uses awsvpc mode with ALB. When a new task starts, how does it register with the ALB target group?', options: [{ id: 'A', text: 'Manually add the task IP to the ALB target group after each deployment' }, { id: 'B', text: 'ECS automatically registers task IPs with the ALB target group on task start and deregisters on task stop' }, { id: 'C', text: 'The ALB discovers tasks via Route 53 DNS records registered by ECS Service Discovery' }, { id: 'D', text: 'The application in the container registers itself with the ALB on startup via SDK calls' }], correct: ['B'], explanation: 'ECS integrates with ALB/NLB target groups automatically. When a task transitions to RUNNING, ECS registers the task\'s IP and port. On task stop, ECS deregisters it respecting the deregistration delay. No manual intervention needed.', distractors: { A: 'Manual IP management is not required — ECS handles target registration/deregistration as part of the service lifecycle.', C: 'ALB uses direct IP targets — not DNS discovery. Cloud Map provides DNS-based discovery separately.', D: 'Target registration is orchestrated by ECS — the application container does not register itself with the ALB.' } },
  { id: 'd3-svc-035', domain: 3, topics: ['Lambda', 'code signing', 'supply chain security'], type: 'single', stem: 'A security policy requires that only cryptographically signed Lambda deployment packages from trusted sources can be deployed. What prevents unsigned code from running?', options: [{ id: 'A', text: 'IAM policies restricting who can call the Lambda UpdateFunctionCode API action' }, { id: 'B', text: 'Lambda code signing with AWS Signer' }, { id: 'C', text: 'S3 bucket policies controlling access to deployment package ZIP files' }, { id: 'D', text: 'VPC endpoint policies for the Lambda API endpoint to restrict deployments' }], correct: ['B'], explanation: 'Lambda code signing uses AWS Signer to sign deployment packages. Functions configured with a code signing configuration reject deployments if unsigned or signed by an untrusted authority. Provides supply-chain integrity for Lambda deployments.', distractors: { A: 'IAM policies control who can call UpdateFunctionCode — not whether the code itself is cryptographically signed.', C: 'S3 bucket policies control access to the ZIP files — not cryptographic signature verification of the code content.', D: 'VPC endpoint policies restrict network access to the Lambda API — not code integrity or signature verification.' } },
  { id: 'd3-svc-036', domain: 3, topics: ['Fargate', 'EFS persistent storage', 'shared state'], type: 'single', stem: 'An ECS Fargate task needs persistent storage that survives task restarts and is shared between multiple concurrent tasks. What provides this?', options: [{ id: 'A', text: 'Fargate ephemeral storage' }, { id: 'B', text: 'Amazon EFS volume' }, { id: 'C', text: 'EBS volume attached to the Fargate task' }, { id: 'D', text: 'S3 sync on task start/stop' }], correct: ['B'], explanation: 'EFS integrates with Fargate tasks as a persistent volume defined in the task definition. Data persists across task restarts, replacements, and multiple concurrent tasks can read/write the same filesystem simultaneously.', distractors: { A: 'Fargate ephemeral storage is lost when the task stops — not persistent.', C: 'EBS volumes cannot be attached to Fargate tasks — EBS requires EC2 instances as the attachment host.', D: 'S3 sync on start/stop adds startup latency and complexity — EFS provides native POSIX filesystem semantics without data copying.' } },
  { id: 'd3-svc-037', domain: 3, topics: ['Lambda', 'VPC cold start', 'Hyperplane'], type: 'single', stem: 'Lambda functions in a VPC had significantly longer cold starts before 2020 due to ENI creation. Is this still true?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes' }, { id: 'D', text: 'Lambda cannot be deployed in a VPC' }], correct: ['B'], explanation: 'The VPC cold start penalty was eliminated with AWS Hyperplane ENI management (2020). ENIs are pre-created and reused across Lambda functions in the same VPC. VPC Lambda cold starts are now comparable to non-VPC Lambda.', distractors: { A: 'Minutes-long VPC Lambda cold starts were accurate before 2020 — the Hyperplane architecture change eliminated this bottleneck.', C: '5+ second VPC Lambda cold starts are historical — Hyperplane reduced this to milliseconds.', D: 'Lambda fully supports VPC configuration — functions in a VPC can access RDS, ElastiCache, and other VPC resources.' } },
  { id: 'd3-svc-038', domain: 3, topics: ['EKS', 'HPA', 'pod autoscaling'], type: 'single', stem: 'An EKS deployment needs to automatically scale the number of pods based on CPU utilization. What Kubernetes resource enables this?', options: [{ id: 'A', text: 'Kubernetes StatefulSet' }, { id: 'B', text: 'Horizontal Pod Autoscaler (HPA)' }, { id: 'C', text: 'Kubernetes DaemonSet' }, { id: 'D', text: 'Kubernetes Job' }], correct: ['B'], explanation: 'HPA monitors pod metrics (CPU, memory, or custom metrics via KEDA) and adjusts the replica count to maintain target utilization. The metrics-server provides metrics to HPA. Works with Deployments, ReplicaSets, and StatefulSets.', distractors: { A: 'StatefulSet manages ordered, stable pod deployment for stateful apps — not metric-based autoscaling.', C: 'DaemonSet runs exactly one pod per node — not a workload autoscaling mechanism.', D: 'Job runs pods to completion for batch workloads — not a continuously-running service with autoscaling.' } },
  { id: 'd3-svc-039', domain: 3, topics: ['Lambda', 'Destinations', 'DLQ comparison'], type: 'single', stem: 'An async Lambda invocation fails after 2 automatic retries. What is the modern recommended approach for handling failed events?', options: [{ id: 'A', text: 'Failed events are silently discarded after retries are exhausted' }, { id: 'B', text: 'Configure a Dead Letter Queue (DLQ)' }, { id: 'C', text: 'CloudWatch Logs automatically captures failed event payloads for investigation' }, { id: 'D', text: 'Lambda Destinations On Failure' }], correct: ['D'], explanation: 'Lambda Destinations On Failure is the modern preferred approach over DLQ. Destinations carry more context (function response, error cause, request ID) compared to DLQ which receives only the original payload. Supports SQS, SNS, EventBridge, and Lambda as destinations.', distractors: { A: 'Lambda retries 2 times (3 total attempts) for async invocations — events are not silently discarded if DLQ/Destination is configured.', B: 'DLQ is valid and supported — Lambda Destinations provides richer failure context and is the modern recommendation.', C: 'CloudWatch Logs captures error messages but not the event payload for replay or investigation.' } },
  { id: 'd3-svc-040', domain: 3, topics: ['ECS', 'blue/green deployment', 'CodeDeploy'], type: 'single', stem: 'An ECS service needs zero-downtime deployments with instant rollback capability by shifting traffic back to the old version. What deployment strategy provides this?', options: [{ id: 'A', text: 'Rolling update' }, { id: 'B', text: 'Blue/Green with CodeDeploy' }, { id: 'C', text: 'Recreate' }, { id: 'D', text: 'Canary deployment' }], correct: ['B'], explanation: 'ECS blue/green (CodeDeploy) creates a new "green" task set alongside "blue." Traffic shifts using ALB weighted target groups. Instant rollback: CodeDeploy re-routes 100% of traffic back to blue immediately. The green task set is terminated after the bake period.', distractors: { A: 'Rolling updates gradually replace tasks — rollback requires redeploying the old version, not instant traffic shifting.', C: 'Recreate stops all tasks before starting new ones — causes downtime between teardown and startup.', D: 'Canary tests a small traffic percentage — does not provide instant full rollback to the previous version.' } },
  { id: 'd3-svc-041', domain: 3, topics: ['Lambda', 'Secrets Manager', 'environment variables'], type: 'single', stem: 'A Lambda function has a database password stored in plaintext environment variables. What is the recommended approach for credentials?', options: [{ id: 'A', text: 'Encrypt environment variables with a Lambda KMS key' }, { id: 'B', text: 'Store in AWS Secrets Manager' }, { id: 'C', text: 'Base64-encode the password in the environment variable' }, { id: 'D', text: 'Use SSM Parameter Store SecureString' }], correct: ['B'], explanation: 'Secrets Manager is recommended for credentials: Lambda fetches secrets at runtime via SDK or the Secrets Manager Lambda extension (which caches and refreshes automatically). Secrets rotate without Lambda redeployment. Better access control than environment variables.', distractors: { A: 'KMS-encrypted environment variables are better than plaintext but the secret is still visible in the Lambda console — Secrets Manager provides better access control and rotation.', C: 'Base64 is encoding, not encryption — provides no security whatsoever.', D: 'SSM Parameter Store SecureString is valid and less expensive — but Secrets Manager provides automatic rotation specifically for credentials.' } },
  { id: 'd3-svc-042', domain: 3, topics: ['ECS', 'health checks', 'Docker HEALTHCHECK'], type: 'single', stem: 'An ECS task is running but the application inside returns errors. What two mechanisms detect health independently?', options: [{ id: 'A', text: 'EC2 instance health check only' }, { id: 'B', text: 'Docker HEALTHCHECK (container-level) + ALB target group health check (application-level HTTP response)' }, { id: 'C', text: 'CloudWatch agent health monitoring' }, { id: 'D', text: 'ECS Agent heartbeat only' }], correct: ['B'], explanation: 'Docker HEALTHCHECK runs inside the container and reports container health to ECS — ECS replaces unhealthy containers. ALB health checks test HTTP responses at the application level — deregisters unhealthy targets before ECS replaces them. Two independent detection layers.', distractors: { A: 'EC2 instance health detects host-level failures — not application-level errors inside containers.', C: 'CloudWatch agent provides OS-level metrics — not container application HTTP health checks.', D: 'ECS Agent heartbeat confirms agent connectivity — not the health of the application running inside the container.' } },
  { id: 'd3-svc-043', domain: 3, topics: ['Lambda', 'payload limits', 'synchronous'], type: 'single', stem: 'A Lambda function is invoked synchronously with a 7 MB payload. What happens?', options: [{ id: 'A', text: 'The invocation succeeds' }, { id: 'B', text: 'The invocation fails' }, { id: 'C', text: 'Lambda automatically compresses the payload to fit within the 6 MB limit' }, { id: 'D', text: 'Lambda stores the payload in S3 automatically and passes the S3 reference to the function' }], correct: ['B'], explanation: 'Lambda synchronous payload limits: 6 MB request and 6 MB response. A 7 MB payload exceeds the limit and the invocation fails. Workaround: store large data in S3, pass the S3 key in a small Lambda payload, and retrieve the data inside the function.', distractors: { A: 'Lambda synchronous limit is 6 MB, not 10 GB — the 10 GB limit applies to container image size, not payloads.', C: 'Lambda does not auto-compress payloads — the invocation fails with an error.', D: 'Automatic S3 storage does not happen — the invocation fails with a 413 RequestEntityTooLargeException.' } },
  { id: 'd3-svc-044', domain: 3, topics: ['ECS', 'Secrets Manager integration', 'task definition'], type: 'single', stem: 'An ECS task needs a database password from Secrets Manager injected as an environment variable without the application fetching it at runtime. How is this configured?', options: [{ id: 'A', text: 'Put the Secrets Manager ARN as the environment variable value' }, { id: 'B', text: 'Use the secrets field in the ECS task definition' }, { id: 'C', text: 'Store the secret in an ECS-specific encrypted secret store configured in the cluster settings' }, { id: 'D', text: 'Bake the secret into the container image with the correct IAM permissions to read it at runtime' }], correct: ['B'], explanation: 'ECS task definitions support a secrets field referencing Secrets Manager ARNs or SSM Parameter Store paths. ECS fetches the secret value at task startup and injects it as an environment variable. The application sees a standard environment variable — no SDK calls needed.', distractors: { A: 'The ARN string would be passed as the environment variable value — the application would receive the ARN, not the secret.', C: 'No ECS-specific secret store exists — Secrets Manager and SSM Parameter Store are the integrated options.', D: 'Baking secrets into container images is a security anti-pattern — secrets are visible in image layer history.' } },
  { id: 'd3-svc-045', domain: 3, topics: ['Lambda', 'invocation types', 'sync vs async'], type: 'single', stem: 'A web API calls Lambda and waits for the response. A batch job triggers Lambda without needing the result. What invocation types correspond to these scenarios?', options: [{ id: 'A', text: 'Both scenarios use RequestResponse' }, { id: 'B', text: 'Web API: RequestResponse (synchronous, connection held open); Batch job: Event (asynchronous, Lambda queues and returns 202)' }, { id: 'C', text: 'Web API uses DryRun invocation; Batch job uses Event invocation type' }, { id: 'D', text: 'Both can use Event invocation with the caller polling for status updates' }], correct: ['B'], explanation: 'Lambda invocation types: RequestResponse (synchronous) — connection held open until function completes, response returned. Event (asynchronous) — Lambda queues the event and returns 202 immediately, processes in background. DryRun validates permissions without executing the handler.', distractors: { A: 'Web API and batch job have different latency requirements — using RequestResponse for the batch job wastes the connection while waiting.', C: 'DryRun validates permissions only — it does not execute the function handler and is not for web API use.', D: 'Event invocation is fire-and-forget — the caller receives only a 202, not a result to poll.' } },
]
